import { sql } from 'drizzle-orm';
import { timestamp, uuid } from 'drizzle-orm/pg-core';

/** Primary key: a random UUID generated by Postgres (`gen_random_uuid()`). */
export const id = () => uuid('id').primaryKey().defaultRandom();

/**
 * A point in time, stored as UTC `timestamptz` (ADR-012). Never use `timestamp`
 * without time zone; wall-clock times with a zone (recurrence rules) get their own columns.
 */
export const instant = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

/** `created_at` / `updated_at`, both set by the database clock. */
export const timestamps = () => ({
  createdAt: instant('created_at').notNull().defaultNow(),
  updatedAt: instant('updated_at')
    .notNull()
    .defaultNow()
    .$onUpdateFn(() => sql`now()`),
});
